#!/usr/bin/env node
// Builds supabase/courses_import.sql from OpenStreetMap golf courses.
//
//   node scripts/import-courses.mjs            # Germany (DE)
//   node scripts/import-courses.mjs AT         # another country, ISO 3166-1 alpha-2 code
//   node scripts/import-courses.mjs DE --from-file overpass.json   # reuse a saved Overpass response
//
// Then run the generated file in the Supabase SQL editor (or: psql "$DATABASE_URL" -f supabase/courses_import.sql).
// It is safe to re-run: rows are matched on osm_id and updated.
//
// Data (c) OpenStreetMap contributors, ODbL. Credit "OpenStreetMap contributors" somewhere in the app (e.g. About screen).

import { readFileSync, writeFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';

const args = process.argv.slice(2);
const country = (args.find((a) => /^[A-Za-z]{2}$/.test(a)) ?? 'DE').toUpperCase();
const fileIdx = args.indexOf('--from-file');
const fromFile = fileIdx >= 0 ? args[fileIdx + 1] : null;
const OUT = new URL('../supabase/courses_import.sql', import.meta.url);

const ENDPOINTS = ['https://overpass-api.de/api/interpreter', 'https://overpass.kumi.systems/api/interpreter'];

const query = `[out:json][timeout:180];
area["ISO3166-1"="${country}"][admin_level=2]->.a;
nwr["leisure"="golf_course"]["name"](area.a);
out center tags;`;

async function fetchOverpass() {
  let lastErr;
  for (const url of ENDPOINTS) {
    try {
      const res = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded', 'User-Agent': 'par-partners-import/1.0' },
        body: 'data=' + encodeURIComponent(query)
      });
      if (!res.ok) throw new Error(`${url} answered ${res.status}`);
      return await res.json();
    } catch (e) {
      lastErr = e;
      console.warn('Overpass request failed, trying next endpoint:', e.message);
    }
  }
  throw lastErr;
}

const sql = (s) => (s == null ? 'null' : `'${String(s).replace(/'/g, "''")}'`);

/** Turn Overpass elements into course rows. Exported shape is tested below. */
export function toRows(elements) {
  const seen = new Set();
  const rows = [];
  for (const el of elements) {
    const lat = el.lat ?? el.center?.lat;
    const lon = el.lon ?? el.center?.lon;
    const name = el.tags?.name?.trim();
    if (lat == null || lon == null || !name) continue;
    if (el.tags.disused || el.tags.abandoned || el.tags['disused:leisure']) continue;
    const osmId = `${el.type}/${el.id}`;
    if (seen.has(osmId)) continue;
    seen.add(osmId);
    rows.push({
      osmId,
      name,
      city: el.tags['addr:city'] ?? el.tags['addr:town'] ?? el.tags['addr:village'] ?? null,
      lat: Number(lat.toFixed(6)),
      lon: Number(lon.toFixed(6))
    });
  }
  return rows.sort((a, b) => a.name.localeCompare(b.name));
}

export function toSqlFile(rows, country) {
  const values = rows
    .map((r) => `  (${sql(r.osmId)}, ${sql(r.name)}, ${sql(r.city)}, ${sql(country)}, extensions.st_point(${r.lon}, ${r.lat})::extensions.geography)`)
    .join(',\n');
  return `-- Generated by scripts/import-courses.mjs on ${new Date().toISOString().slice(0, 10)}.
-- ${rows.length} golf courses in ${country}. Data (c) OpenStreetMap contributors, ODbL.
-- Requires migrations 0001 and 0002. Safe to re-run.
insert into courses (osm_id, name, city, country, location) values
${values}
on conflict (osm_id) do update
  set name = excluded.name,
      city = coalesce(excluded.city, courses.city),
      location = excluded.location;
`;
}

// Run only when executed directly (not when imported by a test)
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const data = fromFile ? JSON.parse(readFileSync(fromFile, 'utf8')) : await fetchOverpass();
  const rows = toRows(data.elements ?? []);
  if (!rows.length) {
    console.error('No courses found. Check the country code, or try again later (Overpass can be busy).');
    process.exit(1);
  }
  writeFileSync(OUT, toSqlFile(rows, country));
  console.log(`Wrote ${rows.length} courses to supabase/courses_import.sql`);
  console.log(`Next: paste that file into the Supabase SQL editor and run it.`);
}
